require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';require_permission($pdo,'view_orders');if(user_role($pdo)!=='client')redirect('/index.php');
$clientId=client_id_for_user($pdo,(int)current_user($pdo)['id']);$active='myorders';$pageTitle='My Orders';$st=$pdo->prepare("SELECT * FROM orders WHERE client_id=? ORDER BY id DESC");$st->execute([$clientId]);$rows=$st->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="mb-4"><span class="eyebrow">CLIENT AREA</span><h1 class="page-title">My Orders</h1></div><div class="panel"><div class="table-responsive"><table class="table stare-table align-middle"><thead><tr><th>Order</th><th>Total</th><th>Address</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><strong>#<?=e($o['order_number'])?></strong></td><td><?=money($o['total_amount'])?></td><td><?=e($o['shipping_address'])?></td><td><?=status_badge($o['status'])?></td><td><?=e(date('Y-m-d H:i',strtotime($o['created_at'])))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center py-5 text-secondary">No orders yet.</td></tr><?php endif;?></tbody></table></div></div>
